import {createSorterSource} from './borrowed-sorter-content.mjs';
import {sorterView,validSorterRun,validSorterSummary,validSorterTrace,validSorterCheck,validSorterKeep,validSorterPart,startSorter,resumeSorter,pageSorter,profileSorter,parcelSorter,editSorter,helpSorter,runSorter,traceSorter,checkSorter,keepSorter,removeSorter,starterSorter} from './borrowed-sorter-core.mjs';
import {stopSpeech} from './play-media.mjs';

const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const own=(o,k)=>Object.hasOwn(o,k),btn=(attrs,text,primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${attrs}>${esc(text)}</button>`;
const retained=label=>`<p class="sorter-retained" data-sorter-unreadable>${esc(label)} stays unchanged in your notebook download, but cannot be read here.</p>`;
const paragraphs=xs=>xs.map(t=>`<p>${esc(t)}</p>`).join('');
const lookup=(xs,id)=>xs.find(x=>x.id===id),destination=(s,id)=>lookup(s.destinations,id)?.label||s.labels.noMajority;
const featureText=(s,features)=>features.length?features.map(id=>lookup(s.features,id)?.label||id).join(', '):'No features';
const datasetText=(s,id)=>id==='augmented'?s.labels.augmentedBatch:s.labels.trainingBatch;
const batchText=(s,id)=>id==='training'?s.labels.trainingBatch:s.labels.testBatch;
const profileText=(s,features,dataset)=>`${featureText(s,features)} · ${datasetText(s,dataset)}`;
const supportText=(s,help)=>`${s.labels.practice} Requested support before this record: ${help.length?help.map(x=>supportLabel(s,x)).join('; '):'none requested'}.`;
function supportLabel(s,key){if(key==='trace')return s.labels.traceSupport;if(key==='run')return s.labels.runSupport;for(const t of s.tasks)for(const h of ['hint','example'])if(key===`${t.id}:${h}`)return `${t.prompt} — ${h}`;for(const d of s.discussions)for(const o of d.options)if(key===`${d.id}:${o.id}`)return `${d.prompt} — ${o.label}`;for(const p of s.parts)if(key===`${p.id}:starter`)return `${p.title} — supplied words used as a starting draft`;return key;}
const percent=n=>n===null?'':`${Math.abs(n-Math.round(n*100)/100)>1e-9?'about ':''}${Math.round(n*100)/100}%`;
const rate=(s,g)=>g.total===0?s.labels.noParcels:`${g.correct} out of ${g.total} · ${percent(g.percent)}`;
function machine(s,features){const cols=s.features.map((f,i)=>{const x=65+i*175,selected=features.includes(f.id);return `<g><rect x="${x}" y="35" width="150" height="48" rx="7" fill="${selected?'#fff1c9':'#e1e9df'}" stroke="#526c5b" stroke-width="2"/><text x="${x+75}" y="65" text-anchor="middle">${esc(f.label)}</text>${selected?`<path d="M${x+75} 83V120" stroke="#8c6720" stroke-width="5"/>`:''}</g>`;}).join('');return `<figure class="sorter-machine"><svg viewBox="0 0 650 250" role="img" aria-label="A pretend sorting machine. Selected features: ${esc(featureText(s,features))}. Examples supply the votes; the result can be Town, Hill or no majority."><path d="M30 15H620V218H30Z" fill="#d5bd8b" stroke="#526c5b" stroke-width="3"/>${cols}<path d="M100 120H550L490 164H160Z" fill="#fffdf6" stroke="#526c5b" stroke-width="3"/><text x="325" y="146" text-anchor="middle">Matching examples vote</text><path d="M255 164L170 192M395 164L480 192" stroke="#526c5b" stroke-width="4"/><path d="M100 182H235V235H100Z" fill="#e9f1e8" stroke="#244f46" stroke-width="3"/><path d="M415 182H550V235H415Z" fill="#f1e6ef" stroke="#704564" stroke-width="3"/><text x="167" y="216" text-anchor="middle">${esc(destination(s,'town'))}</text><text x="482" y="216" text-anchor="middle">${esc(destination(s,'hill'))}</text></svg><figcaption>Ticked features decide which examples match. People chose the procedure, examples and features.</figcaption></figure>`;}
function parcelText(s,row){return s.features.map(f=>lookup(f.values,row[f.id])?.label||row[f.id]).join(' · ');}
function table(s,rows,caption,matched=[]){return `<div class="sorter-table-wrap" tabindex="0" aria-label="${esc(caption)}"><table><caption>${esc(caption)}</caption><thead><tr>${s.features.map(f=>`<th scope="col">${esc(f.label)}</th>`).join('')}${s.destinations.map(d=>`<th scope="col">${esc(d.label)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr${matched.includes(r.id)?' class="sorter-match"':''}>${s.features.map(f=>`<td>${esc(lookup(f.values,r[f.id])?.label||r[f.id])}</td>`).join('')}${s.destinations.map(d=>`<td>${esc(r[d.id])}</td>`).join('')}</tr>`).join('')}</tbody><tfoot><tr><th colspan="${s.features.length}">Total parcels</th>${s.destinations.map(d=>`<td>${rows.reduce((a,r)=>a+r[d.id],0)}</td>`).join('')}</tr></tfoot></table></div><p class="sorter-scroll-note">If the table is wider than the page, swipe or scroll it sideways. Numbers count parcels, not rows.</p>`;}
function reference(w){const s=w.source;return `<details class="sorter-drawer" data-sorter-panel="reference"><summary>Machine card and parcel tables</summary><div class="sorter-instruction"><h2>The instruction card</h2><ol>${s.instructions.map(t=>`<li>${esc(t)}</li>`).join('')}</ol></div><p class="sorter-profile">Current lab: ${esc(profileText(s,w.features,w.dataset))}. Each question names its own settings.</p>${table(s,s.tables.baseline,s.labels.trainingBatch)}${w.dataset==='augmented'?table(s,s.tables.extra,s.labels.extraBatch):''}${table(s,s.tables.test,s.labels.testBatch)}<p>${esc(s.labels.modelBoundary)}</p></details>`;}
function bars(s,r){const all={total:r.total,correct:r.correct,percent:r.percent};return `<div class="sorter-bars">${[['overall','All supplied parcels',all],...s.destinations.map(d=>[d.id,d.label,r.groups[d.id]])].map(([id,label,g])=>`<div><div class="sorter-bar-label"><span>${esc(label)}</span><span>${esc(rate(s,g))}</span></div>${g.total?`<div class="sorter-bar-track" aria-hidden="true"><div class="sorter-bar-fill${id==='hill'?' sorter-hill':''}" style="width:${Math.min(100,Math.max(0,g.percent))}%"></div></div>`:''}</div>`).join('')}</div>`;}
function runCard(r,label,focused=false){const s=r.source;return `<article class="sorter-result"${focused?' data-sorter-run-result tabindex="-1"':''}><h3>${esc(label)}</h3><p class="sorter-profile">${esc(profileText(s,r.features,r.dataset))}</p><p>${esc(batchText(s,r.result.batch))} · correctly routed</p>${bars(s,r.result)}${r.result.undecided?`<p>${r.result.undecided} parcels had no majority and were not routed.</p>`:''}<p>${esc(s.labels.development)}</p>${r.dataset==='augmented'?`<p class="sorter-retained">${esc(s.labels.augmentedWarning)}</p>`:''}${Array.isArray(r.helpBefore)?`<details><summary>Support requested before this run</summary><p class="sorter-small">${esc(supportText(s,r.helpBefore))}</p></details>`:'<p class="sorter-small">Support before this run was not captured in this older advice snapshot.</p>'}<details><summary>Inspect every parcel row</summary><div class="sorter-table-wrap" tabindex="0"><table><caption>Routing in this saved run</caption><thead><tr><th>Parcel features</th><th>Actual destination counts</th><th>Machine routes to</th><th>Correct parcels</th><th>How it voted</th></tr></thead><tbody>${r.result.rows.map(row=>`<tr><th scope="row">${esc(parcelText(s,row.trace.parcel))}</th><td>${s.destinations.map(d=>`${esc(d.label)}: ${row[d.id]}`).join('<br>')}</td><td>${esc(destination(s,row.trace.destination))}</td><td>${row.correctTown+row.correctHill}</td><td>${row.trace.fallback?'Whole-corpus fallback':'Exact matching examples'}; ${s.destinations.map(d=>`${esc(d.label)} ${row.trace.votes[d.id]}`).join(', ')}</td></tr>`).join('')}</tbody></table></div></details></article>`;}
function recentRuns(w){if(!w.runs.length)return '<p>No model run has been kept yet. Try the original card, or choose settings in Try a change.</p>';const latest=w.runs.at(-1),prior=w.runs.slice(0,-1).filter(validSorterRun).at(-1);return `${validSorterRun(latest)?`${prior?`<p>${sameTables(prior.source,latest.source)&&prior.result.batch===latest.result.batch?'These saved runs use the same supplied parcel tables. Compare settings and results; changing several things at once does not isolate one cause.':'These runs use different frozen source tables or evaluation batches. Their counts are not a controlled comparison.'}</p><div class="sorter-comparison">${runCard(prior,'Previous readable run')}${runCard(latest,'Latest run',true)}</div>`:runCard(latest,'Latest run',true)}`:retained('The latest model run')}${w.runs.some(r=>!validSorterRun(r))?retained('An earlier model run'):''}<p class="sorter-small">${w.runs.length} of twenty-four model runs retained. Editing settings never changes a saved run.</p>${w.runs.length>2?`<details class="sorter-history" data-sorter-panel="runs"><summary>All earlier runs</summary>${w.runs.slice(0,-1).map((r,i)=>validSorterRun(r)?runCard(r,`Saved run ${i+1}`):retained(`Run ${i+1}`)).join('')}</details>`:''}`;}
function sameTables(a,b){return JSON.stringify(a.tables)===JSON.stringify(b.tables)&&JSON.stringify(a.features)===JSON.stringify(b.features)&&JSON.stringify(a.destinations)===JSON.stringify(b.destinations);}
function traceCard(r,label='Latest parcel trace',progressive=false){const s=r.source,t=r.trace,training=r.dataset==='augmented'?[...s.tables.baseline,...s.tables.extra]:s.tables.baseline;const steps=['Match only the selected features.',t.matchedIds.length?`${t.matchedIds.length} example row${t.matchedIds.length===1?'':'s'} match; their parcel votes are ${t.matchedCounts.town} ${esc(destination(s,'town'))}, ${t.matchedCounts.hill} ${esc(destination(s,'hill'))}.`:'No example row matches.',`${t.fallback?'Use the whole example corpus because matching examples supplied no votes.':'Use those matching examples.'} Votes: ${s.destinations.map(d=>`${esc(d.label)} ${t.votes[d.id]}`).join(', ')}.`,`Machine routes to: <strong>${esc(destination(s,t.destination))}</strong>.`];return `<article class="sorter-trace" data-sorter-trace-result${progressive?' data-sorter-trace-depth="1"':''} tabindex="-1"><h3>${esc(label)}</h3><p>${esc(parcelText(s,t.parcel))}</p><p class="sorter-profile">${esc(profileText(s,r.features,r.dataset))}</p><ol>${steps.map((text,i)=>`<li${progressive?` data-sorter-trace-step="${i+1}" tabindex="-1"${i>0?' hidden':''}`:''}>${text}</li>`).join('')}</ol>${progressive?`<p data-sorter-trace-progress>Step 1 of 4. Trace disclosure is temporary; the full calculation stays saved.</p><div class="sorter-actions">${btn('data-sorter-next-trace','Next trace step',true)}${btn('data-sorter-full-trace','Show full saved trace')}</div>`:''}<div${progressive?' data-sorter-trace-finish hidden':''}><p>Actual destination counts for this supplied row: ${s.destinations.map(d=>`${esc(d.label)} ${t.parcel[d.id]}`).join(', ')}. The machine does not get to use these answers to route it.</p></div><details><summary>See matching example rows</summary>${table(s,training,'Example rows used for this saved trace',t.matchedIds)}</details><p class="sorter-small">${esc(supportText(s,r.helpBefore))}</p></article>`;}
function trace(w){const s=w.source,last=w.traces.at(-1);return `<section><h3>Follow one parcel</h3><p class="sorter-profile">This trace uses current lab settings: ${esc(profileText(s,w.features,w.dataset))}.</p><label>Parcel from the supplied batch<select data-sorter-parcel>${s.tables.test.map(r=>`<option value="${esc(r.id)}"${w.parcelId===r.id?' selected':''}>${esc(parcelText(s,r))}</option>`).join('')}</select></label>${btn('data-sorter-trace','Trace this parcel',true)}${last===undefined?'':validSorterTrace(last)?traceCard(last,'Latest parcel trace',true):retained('The latest parcel trace')}<p class="sorter-small">${w.traces.length} of twelve parcel traces retained. A trace is supplied support.</p>${w.traces.length>1?`<details class="sorter-history" data-sorter-panel="traces"><summary>Earlier parcel traces</summary>${w.traces.slice(0,-1).map((r,i)=>validSorterTrace(r)?traceCard(r,`Parcel trace ${i+1}`):retained(`Trace ${i+1}`)).join('')}</details>`:''}</section>`;}
function checkCard(c,label){const s=c.source,t=lookup(s.tasks,c.taskId);return `<article class="sorter-result"><h4>${esc(label)}</h4><p>${esc(t.prompt)}</p><p class="sorter-profile">${esc(profileText(s,c.profile.features,c.profile.dataset))} · ${esc(batchText(s,t.batch))}</p><p>Your response: <strong>${esc(t.kind==='choice'?lookup(t.choices,c.raw)?.label||c.raw:c.raw)}</strong>.</p><p data-sorter-saved-outcome>${c.outcome==='match'?'Matches the supplied answer.':'Differs from the supplied answer.'}</p><p>${esc(c.feedback)}</p><p class="sorter-small">${esc(supportText(s,c.helpBefore))}</p><details><summary>Supplied model context kept with this response</summary>${runCard({source:s,features:c.profile.features,dataset:c.profile.dataset,result:c.resultContext,helpBefore:c.helpBefore},'Fixed question settings')}</details></article>`;}
function taskCard(w,t,index){const entry=own(w.answers,t.id)?w.answers[t.id]:undefined,brokenDraft=own(w.answers,t.id)&&(typeof entry!=='string'||entry.length>40||(t.kind==='choice'&&entry!==''&&!t.choices.some(o=>o.id===entry))),raw=!brokenDraft&&typeof entry==='string'?entry:'';const checks=w.checks.filter(c=>c?.taskId===t.id),latest=checks.at(-1);return `<details class="sorter-task" data-sorter-task="${esc(t.id)}" data-sorter-panel="task-${esc(t.id)}"${index===0?' open':''}><summary>${esc(t.prompt)}</summary><p class="sorter-profile">Question settings: ${esc(profileText(w.source,t.profile.features,t.profile.dataset))}. Batch: ${esc(batchText(w.source,t.batch))}.${t.denominator===null?'':` Denominator: ${esc(t.denominator)}.`}</p>${brokenDraft?retained('This question’s draft'):`<label>${t.kind==='integer'?'Your number':'Your choice'}${t.kind==='integer'?`<input type="text" inputmode="numeric" autocomplete="off" maxlength="40" data-sorter-answer="${esc(t.id)}" data-sorter-draft value="${esc(raw)}">`:`<select data-sorter-answer="${esc(t.id)}"><option value="">Choose an idea</option>${t.choices.map(c=>`<option value="${esc(c.id)}"${raw===c.id?' selected':''}>${esc(c.label)}</option>`).join('')}</select>`}</label>`}<div class="sorter-actions">${brokenDraft?'':btn(`data-sorter-check="${esc(t.id)}"`,'Check my working',true)}${btn(`data-sorter-help="${esc(t.id)}:hint"`,'Hint')}${btn(`data-sorter-help="${esc(t.id)}:example"`,'A different example')}</div>${['hint','example'].map(h=>w.help.includes(`${t.id}:${h}`)?`<aside class="sorter-help-text" data-sorter-help-text="${esc(t.id)}:${h}" tabindex="-1"><strong>${h==='hint'?'Hint':'A different example'}</strong><p>${esc(t[h])}</p></aside>`:'').join('')}<div data-sorter-result="${esc(t.id)}" tabindex="-1">${latest===undefined?'':validSorterCheck(latest)?checkCard(latest,'Latest check for this question'):retained('The latest check for this question')}</div>${own(w.firstChecks,t.id)?`<details class="sorter-history"><summary>First response kept as answered</summary>${validSorterCheck(w.firstChecks[t.id])?checkCard(w.firstChecks[t.id],'First check'):retained('The first check')}</details>`:''}</details>`;}
function tasks(w){return w.source.tasks.filter(t=>t.page===w.page).map((t,i)=>taskCard(w,t,i)).join('');}
function discussion(w){return w.source.discussions.filter(d=>d.page===w.page).map(d=>`<section class="sorter-discussions"><h3>${esc(d.prompt)}</h3><p>Explore these ideas together. These choices are not marked right or wrong.</p><div class="sorter-actions">${d.options.map(o=>btn(`data-sorter-discussion="${esc(d.id)}:${esc(o.id)}"`,o.label)).join('')}</div>${d.options.filter(o=>w.help.includes(`${d.id}:${o.id}`)).map(o=>`<aside class="sorter-help-text" data-sorter-discussion-text="${esc(d.id)}:${esc(o.id)}" tabindex="-1"><strong>${esc(o.label)}</strong><p>${esc(o.reply)}</p></aside>`).join('')}</section>`).join('');}
function controls(w){const s=w.source;return `<section class="sorter-controls"><h3>What may the machine look at?</h3><fieldset><legend>Selected features</legend><div class="sorter-features">${s.features.map(f=>`<label><input type="checkbox" data-sorter-feature="${esc(f.id)}"${w.features.includes(f.id)?' checked':''}>${esc(f.label)}</label>`).join('')}</div></fieldset><label>Examples to consult<select data-sorter-dataset><option value="baseline"${w.dataset==='baseline'?' selected':''}>${esc(s.labels.trainingBatch)}</option><option value="augmented"${w.dataset==='augmented'?' selected':''}>${esc(s.labels.augmentedBatch)}</option></select></label><p>Empty feature selection matches every example. Selecting the same settings again adds nothing.</p>${w.dataset==='augmented'?`<p class="sorter-retained">${esc(s.labels.augmentedWarning)}</p>`:''}<div class="sorter-actions">${btn('data-sorter-run=""','Run this model',true)}</div><h3>Try a named comparison</h3><p>Each button restores its named settings and keeps a new run. Earlier results and writing stay unchanged.</p><div class="sorter-actions">${s.presets.filter(p=>p.id!=='original').map(p=>btn(`data-sorter-run="${esc(p.id)}"`,p.label)).join('')}</div></section>`;}
const readablePart=(w,p)=>!own(w.plan,p.id)||(validSorterPart(w.plan[p.id])&&(w.plan[p.id].choiceId===''||p.options.some(o=>o.id===w.plan[p.id].choiceId)));
const draft=(w,id)=>{const p=lookup(w.source.parts,id);return p&&own(w.plan,id)&&readablePart(w,p)?w.plan[id]:{mode:'own',own:'',choiceId:''};};
function summaryCard(r,keptSource,label){const s=own(r,'source')?r.source:keptSource;return `<article class="sorter-result" data-sorter-kept-run-summary><h4>${esc(label)}</h4><p class="sorter-profile">${esc(profileText(s,r.features,r.dataset))}</p><p>${esc(batchText(s,r.result.batch))} · correctly routed</p>${JSON.stringify(s)!==JSON.stringify(keptSource)?`<p class="sorter-retained">This summary retains a different frozen source: ${esc(s.title)}. Do not treat it as a controlled comparison with this advice’s other source.</p>`:''}${bars(s,r.result)}${r.result.undecided?`<p>${r.result.undecided} parcels had no majority and were not routed.</p>`:''}<p>${esc(s.labels.development)}</p>${r.dataset==='augmented'?`<p class="sorter-retained">${esc(s.labels.augmentedWarning)}</p>`:''}<p class="sorter-small">${Array.isArray(r.helpBefore)?esc(supportText(s,r.helpBefore)):'Support before this run was not captured in this older advice snapshot.'}</p><p class="sorter-small">This advice snapshot keeps aggregate results rather than copying every row trace.</p></article>`;}
function keptRun(r,k,i){if(r?.summary===true)return validSorterSummary(r,k.source)?summaryCard(r,k.source,`Kept run ${i+1}`):retained(`Kept run ${i+1}`);return validSorterRun(r&&own(r,'helpBefore')?r:{...r,helpBefore:[]})?runCard(r,`Kept run ${i+1}`):retained(`Kept run ${i+1}`);}

function kept(k,label){const s=k.source;return `<article class="sorter-kept" data-sorter-kept><h3>${esc(label)}</h3><div class="sorter-letter">${k.renderedParts.map(p=>`<section><h4>${esc(p.title)}</h4><p>${p.text?esc(p.text):'Not yet written.'}</p><p class="sorter-small">${p.mode==='supplied'?'Supplied words':'Own writing'} · kept as written</p></section>`).join('')}</div><p>${esc(s.labels.closing)}</p><p class="sorter-small">${esc(supportText(s,k.helpBefore))}</p><details><summary>Model results available when this advice was kept</summary>${k.runs.length?k.runs.map((r,i)=>keptRun(r,k,i)).join(''):'<p>No model run was kept with this advice.</p>'}</details></article>`;}
function plan(w){const s=w.source;return `<section><p>Choose supplied words, write your own, or use supplied words as a starting draft. You can keep unfinished advice and return later. No letter is sent outside this game.</p>${s.parts.map(p=>{const d=draft(w,p.id),malformed=!readablePart(w,p);return `<section class="sorter-plan-part"><h3>${esc(p.title)}</h3>${malformed?retained('This part’s earlier draft'):`<div class="sorter-plan-modes">${['own','supplied'].map(mode=>btn(`data-sorter-plan-mode="${esc(p.id)}" data-mode="${mode}" aria-pressed="${d.mode===mode}"`,mode==='own'?'Write your own':'Choose supplied words')).join('')}</div>${d.mode==='own'?`<label>Your words<textarea maxlength="1200" data-sorter-plan-text="${esc(p.id)}" data-sorter-draft>${'\n'}${esc(d.own)}</textarea></label>`:`<label>Supplied words<select data-sorter-plan-choice="${esc(p.id)}"><option value="">Choose a sentence</option>${p.options.map(o=>`<option value="${esc(o.id)}"${d.choiceId===o.id?' selected':''}>${esc(o.text)}</option>`).join('')}</select></label><div class="sorter-actions">${btn(`data-sorter-adapt="${esc(p.id)}"`,'Use these words as a starting draft')}</div><p class="sorter-small">Switching modes or choices preserves your own draft. Copying supplied words into it asks before replacing nonempty writing.</p>`}`}</section>`;}).join('')}<div class="sorter-actions">${btn('data-sorter-keep','Keep this advice',true)}</div><p>Keeping advice does not finish or mark any other page. Your experiments and revisions remain open.</p><div data-sorter-plan-result tabindex="-1">${own(w,'kept')?validSorterKeep(w.kept)?kept(w.kept,'Latest advice kept'):retained('The latest advice'):'<p>No advice has been kept yet.</p>'}</div>${own(w,'firstKept')?`<details class="sorter-history" data-sorter-panel="first-advice"><summary>First advice kept as written</summary>${validSorterKeep(w.firstKept)?kept(w.firstKept,'First advice kept'):retained('The first advice')}</details>`:''}</section>`;}
function visits(v){return v.visits.length?`<details class="sorter-visits" data-sorter-panel="visits"><summary>Your visits (${v.visits.length})</summary><div class="sorter-actions">${v.visits.map(x=>x.readable?btn(`data-sorter-resume="${esc(x.id)}" aria-pressed="${x.id===v.current}"`,x.title):retained(`Visit ${x.id}`)).join('')}</div></details>`:'';}
function storage(v){return v.visits.length?`<details class="sorter-storage" data-sorter-panel="storage"><summary>Make room deliberately</summary><p>Download your notebook before removing a visit if you want to keep a copy. Removing it also removes its original sources, checks, traces, experiments and advice.</p><a class="secondary" href="#notes">Open notes to download</a><label>Visit to remove<select data-sorter-remove-choice><option value="">Choose a visit</option>${v.visits.map(x=>`<option value="${esc(x.id)}">${esc(x.title||x.id)}${x.readable?'':' · unreadable'}</option>`).join('')}</select></label>${btn('data-sorter-remove','Remove selected visit')}</details>`:'';}
const footer=()=>'<footer><a href="#desk">Keeper’s Desk</a><a href="#post/sorting/order">Which test first?</a><a href="#pathways/science">Science starting points</a><a href="#notes">Grown-up notes</a></footer>';
export const sorterEntry=()=>'<aside class="sorter-entry"><h2>The Borrowed Sorting Machine</h2><p>Inspect a parcel sorter, try different examples and features, and ask: right for whom?</p><a class="secondary" href="#learn/computing/sorting">Open the sorting investigation</a></aside>';
export function sorterPage(state){const v=sorterView(state),w=v.work,s=w?.source||createSorterSource(1),header=`<section class="sorter-page" data-sorter-root><header class="sorter-header"><a class="secondary" href="#desk">Back to the Keeper’s Desk</a><h1>The Borrowed Sorting Machine</h1><p class="sorter-fiction">Fictional parcels · an inspectable desk model</p></header>`,status='<p class="sorter-status" id="sorter-status" role="status" aria-live="polite" tabindex="-1"></p><div class="sorter-pending" data-sorter-pending-actions hidden><p>Some visible words have not been saved. Copy them, edit the marked field to try again, or deliberately restore the saved words.</p>'+btn('data-sorter-restore','Restore saved words')+'</div>';if(v.status==='unavailable')return header+'<h2 id="sorter-heading" tabindex="-1">Earlier format retained</h2><p>This version cannot edit this earlier notebook format. It remains downloadable unchanged; other destinations are open.</p>'+status+footer()+'</section>';if(!w)return header+`<h2 id="sorter-heading" tabindex="-1">A machine on loan, and a goat at the door</h2><p>${esc(s.story)}</p><p>${esc(s.labels.modelBoundary)}</p>${v.status==='unreadable'?retained('The selected visit'):''}<div class="sorter-actions">${btn('data-sorter-start','Open the borrowed machine',true)}</div>${visits(v)}${storage(v)}${status}${footer()}</section>`;
 const page=s.pages[w.page];return header+`<p>${esc(s.title)}</p><nav class="sorter-pages" aria-label="Sorting investigation pages">${s.pages.map((p,i)=>btn(`data-sorter-page="${i}" aria-current="${w.page===i?'step':'false'}"`,p.title)).join('')}</nav><section class="sorter-turn"><h2 id="sorter-heading" tabindex="-1">${esc(page.title)}</h2>${paragraphs(page.teaching)}${page.example?`<aside class="sorter-teaching"><h3>A different worked example</h3><p>${esc(page.example)}</p></aside>`:''}${w.page===0?machine(s,w.features):''}${reference(w)}${w.page===0?trace(w):w.page===1?`<div class="sorter-actions">${btn('data-sorter-run="original"','Run the original card',true)}</div>${recentRuns(w)}`:w.page===3?`${controls(w)}${recentRuns(w)}${trace(w)}`:w.page===4?plan(w):''}${w.page!==4?tasks(w)+discussion(w):''}</section><nav class="sorter-arrows" aria-label="Previous and next page">${w.page?btn(`data-sorter-page="${w.page-1}"`,`Previous: ${s.pages[w.page-1].title}`):''}${w.page<4?btn(`data-sorter-page="${w.page+1}"`,`Next: ${s.pages[w.page+1].title}`,true):''}</nav>${status}${w.checks.some(c=>!c||typeof c.taskId!=='string'||!s.tasks.some(t=>t.id===c.taskId))?retained('A check that cannot be matched to these questions'):''}<p class="sorter-small">${w.checks.length} of forty-eight checked responses retained. All checked responses are supported practice; no proficiency is inferred.</p><div class="sorter-actions">${btn('data-sorter-start','Start another visit')}</div>${visits(v)}${storage(v)}<details class="sorter-grownups" data-sorter-panel="grownups"><summary>Grown-ups · what this model can show</summary><p>${esc(s.labels.modelBoundary)}</p><p>${esc(s.labels.development)}</p><p>People choose the procedure, features and examples. These fictional destination counts do not establish comprehensive fairness or independent learning. Tasks retain their own settings and original responses; advice is not automatically graded.</p></details>${footer()}</section>`;}
export function sorterNotes(state){if(!own(state,'borrowedSorter'))return '';const v=sorterView(state);return `<details class="panel sorter-notes"><summary>The Borrowed Sorting Machine · examples, decisions and advice</summary><p>Fictional lookup-model experiments, supplied support and original checked responses remain separate. No real AI, independent proficiency, comprehensive fairness or future performance is inferred.</p>${v.status==='unavailable'?'<p>Earlier format retained unchanged.</p>':v.visits.map(x=>x.readable?`<p>${esc(x.title||x.id)}: ${v.root.visits[x.id].runs.length} model runs, ${v.root.visits[x.id].traces.length} parcel traces, ${v.root.visits[x.id].checks.length} checked responses retained. ${own(v.root.visits[x.id],'kept')?'Advice has a kept version.':'No advice kept yet.'}</p>`:retained(`Visit ${x.id}`)).join('')}<details><summary>Exact frozen sources, writing and results</summary><pre>${esc(JSON.stringify(state.borrowedSorter,null,2))}</pre></details></details>`;}

let removeGuards=()=>{},pendingNavigation=()=>false;
export const guardSorterNavigation=()=>pendingNavigation();
export function bindSorter(state,{save,render,focus,canExport,explorerId,isActive}={}){
 removeGuards();removeGuards=()=>{};const root=document.querySelector('[data-sorter-root]');if(!root)return;const owner=explorerId?.(),route=location.hash,o={canExport},dirty=new Set();
 const live=el=>root.isConnected&&el?.isConnected&&root.contains(el)&&document.querySelector('[data-sorter-root]')===root&&location.hash===route&&explorerId?.()===owner&&(!isActive||isActive());
 const say=(message,take=false)=>{const el=root.querySelector('#sorter-status');if(el){el.textContent=message;if(take)el.focus();}};
 const pendingMessage='Your visible words have not been saved. Edit the marked field to try again, or copy them and choose Restore saved words before continuing.';
 const pendingUI=()=>{const el=root.querySelector('[data-sorter-pending-actions]');if(el)el.hidden=!dirty.size;};
 const find=(next,selector)=>[...(next?.querySelectorAll(selector)||[])].find(el=>el.getClientRects().length);
 const redraw=(message='',target='#sorter-heading')=>{const panels=new Map([...root.querySelectorAll('details[data-sorter-panel]')].map(el=>[el.dataset.sorterPanel,el.open]));stopSpeech();save?.();render?.();const next=document.querySelector('[data-sorter-root]');next?.querySelectorAll('details[data-sorter-panel]').forEach(el=>{if(panels.has(el.dataset.sorterPanel))el.open=panels.get(el.dataset.sorterPanel);});const status=next?.querySelector('#sorter-status');if(status)status.textContent=message;const el=find(next,target);el?.focus();if(!el||document.activeElement!==el)focus?.('#sorter-heading');};
 const fail=()=>say('This change could not be kept safely. Earlier work stays unchanged. Open notes to download your notebook before making room, or try another visit.',true);
 const act=(el,fn,message='',target='#sorter-heading')=>{if(!live(el))return;if(dirty.size){say(pendingMessage,true);return;}const r=fn();if(!r)return fail();if(r.recorded===false)return say(r.feedback,true);redraw(message,target);};
 const on=(selector,fn)=>root.querySelectorAll(selector).forEach(el=>el.addEventListener('click',()=>{if(live(el))fn(el);}));
 const capped=(field,max,message,fn)=>sorterView(state).work?.[field].length>=max?{recorded:false,feedback:message}:fn();
 on('[data-sorter-start]',el=>act(el,()=>sorterView(state).visits.length>=16?{recorded:false,feedback:'Sixteen visits are retained. Download notes, then deliberately remove a selected visit if you need room.'}:startSorter(state,o),'A fresh visit is open. Earlier work stays retained.'));
 on('[data-sorter-resume]',el=>act(el,()=>resumeSorter(state,el.dataset.sorterResume,o),'Original visit resumed.'));
 on('[data-sorter-page]',el=>act(el,()=>pageSorter(state,Number(el.dataset.sorterPage),o)));
 on('[data-sorter-run]',el=>act(el,()=>capped('runs',24,'This visit retains twenty-four model runs. Earlier experiments stay unchanged. You can edit and keep advice or open another visit.',()=>runSorter(state,el.dataset.sorterRun||null,o)),'Model result kept with its settings and source.','[data-sorter-run-result]'));
 on('[data-sorter-trace]',el=>act(el,()=>capped('traces',12,'This visit retains twelve parcel traces. Earlier traces stay unchanged. You can still compare results, answer questions or open another visit.',()=>traceSorter(state,o)),'The parcel trace is supplied support.','[data-sorter-trace-result]'));
 const revealTrace=(el,full)=>{if(dirty.size)return say(pendingMessage,true);const card=el.closest('[data-sorter-trace-depth]');if(!live(el)||!card)return;const previous=Number(card.dataset.sorterTraceDepth),depth=full?4:Math.min(4,previous+1);card.dataset.sorterTraceDepth=String(depth);card.querySelectorAll('[data-sorter-trace-step]').forEach(li=>{li.hidden=Number(li.dataset.sorterTraceStep)>depth;});const finish=card.querySelector('[data-sorter-trace-finish]');if(finish)finish.hidden=depth<4;const progress=card.querySelector('[data-sorter-trace-progress]');if(progress)progress.textContent=`Step ${depth} of 4. Trace disclosure is temporary; the full calculation stays saved.`;const next=card.querySelector('[data-sorter-next-trace]');if(next)next.disabled=depth===4;const line=card.querySelector(`[data-sorter-trace-step="${depth}"]`);line?.focus();say(depth===4?'Full saved trace shown. No new notebook change.':`Trace step ${depth} shown. No new notebook change.`);};
 on('[data-sorter-next-trace]',el=>revealTrace(el,false));
 on('[data-sorter-full-trace]',el=>revealTrace(el,true));
 on('[data-sorter-check]',el=>act(el,()=>capped('checks',48,'This visit retains forty-eight checked responses. You can still edit and keep advice, compare earlier runs or open another visit.',()=>checkSorter(state,el.dataset.sorterCheck,o)),'Checked response kept as answered.',`[data-sorter-result="${el.dataset.sorterCheck}"]`));
 on('[data-sorter-help]',el=>act(el,()=>helpSorter(state,el.dataset.sorterHelp,o),'Support kept before showing it.',`[data-sorter-help-text="${el.dataset.sorterHelp}"]`));
 on('[data-sorter-discussion]',el=>act(el,()=>helpSorter(state,el.dataset.sorterDiscussion,o),'Discussion opened without marking an answer.',`[data-sorter-discussion-text="${el.dataset.sorterDiscussion}"]`));
 on('[data-sorter-plan-mode]',el=>{const w=sorterView(state).work,d=draft(w,el.dataset.sorterPlanMode);act(el,()=>editSorter(state,'plan',el.dataset.sorterPlanMode,{...d,mode:el.dataset.mode},o),'Both writing drafts remain kept.',`[data-sorter-plan-mode="${el.dataset.sorterPlanMode}"][data-mode="${el.dataset.mode}"]`);});
 on('[data-sorter-adapt]',el=>{if(dirty.size)return say(pendingMessage,true);const w=sorterView(state).work,d=draft(w,el.dataset.sorterAdapt);if(!d.choiceId)return say('Choose supplied words first.',true);if(d.own&&!window.confirm('Replace this part’s own writing with the selected supplied words? Your kept advice stays unchanged.'))return;if(!live(el))return;act(el,()=>starterSorter(state,el.dataset.sorterAdapt,true,o),'Supplied words copied into your own draft; you can change them.',`[data-sorter-plan-text="${el.dataset.sorterAdapt}"]`);});
 on('[data-sorter-keep]',el=>act(el,()=>keepSorter(state,o),'Advice kept. First and latest versions remain separate.','[data-sorter-plan-result]'));
 on('[data-sorter-remove]',el=>{if(dirty.size)return say(pendingMessage,true);const id=root.querySelector('[data-sorter-remove-choice]')?.value;if(!id)return say('Choose a visit to remove.',true);if(!window.confirm('Remove only this selected visit, including its sources, experiments, traces, original responses and kept advice? Download your notebook first if you want a copy.'))return;if(!live(el))return;act(el,()=>removeSorter(state,id,true,o),'Selected visit removed. Other work stays available.');});
 const select=(selector,fn,before,target)=>root.querySelectorAll(selector).forEach(el=>el.addEventListener('change',()=>{if(!live(el))return;const old=before(el);if(dirty.size){el.value=old;return say(pendingMessage,true);}act(el,()=>{const r=fn(el);if(!r||r.recorded===false)el.value=old;return r;},'Selection kept.',typeof target==='function'?target(el):target);}));
 select('[data-sorter-parcel]',el=>parcelSorter(state,el.value,o),()=>sorterView(state).work.parcelId,'[data-sorter-parcel]');
 select('[data-sorter-dataset]',el=>profileSorter(state,sorterView(state).work.features,el.value,o),()=>sorterView(state).work.dataset,'[data-sorter-dataset]');
 root.querySelectorAll('[data-sorter-feature]').forEach(el=>el.addEventListener('change',()=>{if(!live(el))return;const w=sorterView(state).work,before=w.features.includes(el.dataset.sorterFeature);if(dirty.size){el.checked=before;return say(pendingMessage,true);}const next=[...root.querySelectorAll('[data-sorter-feature]:checked')].map(x=>x.dataset.sorterFeature);act(el,()=>{const r=profileSorter(state,next,w.dataset,o);if(!r)el.checked=before;return r;},'Features kept. Earlier runs stay unchanged.',`[data-sorter-feature="${el.dataset.sorterFeature}"]`);}));
 select('select[data-sorter-answer]',el=>editSorter(state,'answer',el.dataset.sorterAnswer,el.value,o),el=>{const a=sorterView(state).work.answers;return own(a,el.dataset.sorterAnswer)&&typeof a[el.dataset.sorterAnswer]==='string'?a[el.dataset.sorterAnswer]:'';},el=>`[data-sorter-answer="${el.dataset.sorterAnswer}"]`);
 select('[data-sorter-plan-choice]',el=>editSorter(state,'plan',el.dataset.sorterPlanChoice,{...draft(sorterView(state).work,el.dataset.sorterPlanChoice),choiceId:el.value},o),el=>draft(sorterView(state).work,el.dataset.sorterPlanChoice).choiceId,el=>`[data-sorter-plan-choice="${el.dataset.sorterPlanChoice}"]`);
 const input=(el,key,fn)=>el.addEventListener('input',()=>{if(!live(el))return;if(!fn(el.value)){dirty.add(key);el.setAttribute('aria-invalid','true');pendingUI();say(pendingMessage);return;}dirty.delete(key);el.removeAttribute('aria-invalid');save?.();pendingUI();say(dirty.size?pendingMessage:'Words saved.');});
 root.querySelectorAll('input[data-sorter-answer]').forEach(el=>input(el,`answer-${el.dataset.sorterAnswer}`,raw=>editSorter(state,'answer',el.dataset.sorterAnswer,raw,o)));
 root.querySelectorAll('[data-sorter-plan-text]').forEach(el=>input(el,`plan-${el.dataset.sorterPlanText}`,raw=>editSorter(state,'plan',el.dataset.sorterPlanText,{...draft(sorterView(state).work,el.dataset.sorterPlanText),own:raw},o)));
 on('[data-sorter-restore]',el=>{if(!live(el)||!window.confirm('Discard visible unsaved edits and restore this page’s last saved words? Earlier saved work stays unchanged.'))return;dirty.clear();redraw('Last saved words restored.');});
 const guard=e=>{if(e.type==='keydown'&&!['Enter',' '].includes(e.key))return;if(!root.isConnected||location.hash!==route||explorerId?.()!==owner||!dirty.size)return;const target=e.target;if(target?.closest?.('[data-sorter-draft],[data-sorter-restore]'))return;if(target?.closest?.('button,a,input,select,summary')){e.preventDefault();e.stopImmediatePropagation();say(pendingMessage);}};
 pendingNavigation=()=>{if(!root.isConnected||explorerId?.()!==owner||!dirty.size)return false;history.replaceState(null,'',route);say(pendingMessage);return true;};
 const beforeLeave=e=>{if(dirty.size&&root.isConnected){e.preventDefault();e.returnValue='';}};
 document.addEventListener('click',guard,true);document.addEventListener('keydown',guard,true);window.addEventListener('beforeunload',beforeLeave);
 removeGuards=()=>{document.removeEventListener('click',guard,true);document.removeEventListener('keydown',guard,true);window.removeEventListener('beforeunload',beforeLeave);pendingNavigation=()=>false;};
}
